    private readonly Slider ySlider = new() { Minimum = -1024, Maximum = 2048, Value = 250, TickFrequency = 16 };
    private readonly Slider scaleSlider = new() { Minimum = .1, Maximum = 3.5, Value = 1, TickFrequency = .1 };
    private readonly Slider rotationSlider = new() { Minimum = -180, Maximum = 180, Value = 0, TickFrequency = 5 };
    private readonly Slider opacitySlider = new() { Minimum = 0, Maximum = 1, Value = 1, TickFrequency = .1 };
    private readonly TextBlock xValue = new() { Foreground = Brush("#B8C4DD") };
    private readonly TextBlock yValue = new() { Foreground = Brush("#B8C4DD") };
    private readonly TextBlock scaleValue = new() { Foreground = Brush("#B8C4DD") };
    private readonly TextBlock rotationValue = new() { Foreground = Brush("#B8C4DD") };
