    private bool loadingCanvasSize;

    public event Action<string>? CompositeExported;
    public event Action<string>? CompositeExportedFor2D;

    public WaifuSpriteStudioWindow(string avatarDataDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(avatarDataDirectory);
        workDirectory = Path.Combine(Path.GetFullPath(avatarDataDirectory), "waifu-studio");
        importDirectory = Path.Combine(workDirectory, "imports");
        assetsDirectory = Path.Combine(workDirectory, "built-in-assets");
        userCatalogPath = Path.Combine(workDirectory, "user-assets.json");
        Directory.CreateDirectory(importDirectory);
        catalog = WaifuSpriteAssetCatalog.EnsureAssets(assetsDirectory).ToList();
        LoadPersistedUserAssets();

        Title = "VTuberBot · Creador de waifu PNG por objetos";
        Width = 1500;
        Height = 940;
        MinWidth = 1150;
        MinHeight = 740;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;
        Background = Brush("#0D1220");
        Foreground = Brush("#F8FAFC");
        Content = BuildLayout();

        categoryPicker.ItemsSource = SupportedCategories;
        categoryPicker.SelectedItem = "Sombreros";
        categoryPicker.SelectionChanged += (_, _) => RefreshCatalog();
        canvasSizePicker.ItemsSource = new[]
        {
            "Cuadrado · 1024 × 1024",
            "HD · 1280 × 720",
            "Full HD · 1920 × 1080"
        };
        canvasSizePicker.SelectedIndex = 0;
        canvasSizePicker.SelectionChanged += (_, _) =>
        {
            if (!loadingCanvasSize)
                ChangeCanvasSize();
        };
        catalogList.SelectionChanged += (_, _) => UpdateCatalogDescription();
        layerList.SelectionChanged += (_, _) => LoadSelectedLayerTransform();
        xSlider.ValueChanged += (_, _) => PreviewSelectedTransform();
        ySlider.ValueChanged += (_, _) => PreviewSelectedTransform();
        scaleSlider.ValueChanged += (_, _) => PreviewSelectedTransform();
        rotationSlider.ValueChanged += (_, _) => PreviewSelectedTransform();
        opacitySlider.ValueChanged += (_, _) => PreviewSelectedTransform();
        animationTimer.Tick += (_, _) => AdvanceAnimatedLayers();
        canvas.DragOver += (_, e) => e.Effects = e.Data.GetDataPresent(DataFormats.FileDrop) ? DragDropEffects.Copy : DragDropEffects.None;
        canvas.Drop += (_, e) =>
        {
            if (e.Data.GetData(DataFormats.FileDrop) is string[] files && files.Length > 0)
                ImportDroppedFile(files[0]);
        };
        Loaded += (_, _) => { RefreshCatalog(); animationTimer.Start(); };
        Closed += (_, _) => animationTimer.Stop();
        SetStatus("Listo. Importá un PNG, elegí objetos del catálogo y arrastralos sobre el lienzo. Todo se procesa localmente.");
    }

