    private void ChangeCanvasSize()
    {
        var size = canvasSizePicker.SelectedItem?.ToString() switch
        {
            "HD · 1280 × 720" => (Width: 1280, Height: 720),
            "Full HD · 1920 × 1080" => (Width: 1920, Height: 1080),
            _ => (Width: DefaultCanvasWidth, Height: DefaultCanvasHeight)
        };
        if (size.Width == canvasWidth && size.Height == canvasHeight)
            return;

        var oldWidth = canvasWidth;
        var oldHeight = canvasHeight;
        var scale = Math.Min((double)size.Width / oldWidth, (double)size.Height / oldHeight);
        foreach (var layer in layers)
        {
            if (string.Equals(layer.Category, "Fondos", StringComparison.OrdinalIgnoreCase))
            {
                layer.X = 0;
                layer.Y = 0;
                layer.Width = size.Width;
                layer.Height = size.Height;
                continue;
            }

            var centerX = layer.X + layer.Width / 2;
            var centerY = layer.Y + layer.Height / 2;
            layer.Width *= scale;
            layer.Height *= scale;
            layer.X = size.Width / 2d + (centerX - oldWidth / 2d) * scale - layer.Width / 2d;
            layer.Y = size.Height / 2d + (centerY - oldHeight / 2d) * scale - layer.Height / 2d;
        }

        SetCanvasDimensions(size.Width, size.Height);
        RefreshVisuals();
        if (selectedLayerId is Guid selected && layers.Any(layer => layer.Id == selected))
            SelectLayer(selected);
        SetStatus($"Lienzo cambiado a {canvasWidth} × {canvasHeight}. Se mantuvieron las capas y se reubicaron respecto del centro.");
    }

    private void SetCanvasDimensions(int width, int height)
    {
        if (!IsSupportedCanvasSize(width, height))
            throw new InvalidDataException("Los lienzos admitidos son 1024×1024, 1280×720 y 1920×1080.");
        canvasWidth = width;
        canvasHeight = height;
        canvas.Width = width;
        canvas.Height = height;
        stageGrid.Width = width;
        stageGrid.Height = height;
    }

    private static bool IsSupportedCanvasSize(int width, int height) =>
        (width == DefaultCanvasWidth && height == DefaultCanvasHeight) ||
        (width == 1280 && height == 720) ||
        (width == 1920 && height == 1080);

    private static string CanvasSizeLabel(int width, int height) =>
        (width, height) switch
        {
            (1280, 720) => "HD · 1280 × 720",
            (1920, 1080) => "Full HD · 1920 × 1080",
            _ => "Cuadrado · 1024 × 1024"
        };

    private void RefreshCatalog()
    {
        var selectedCategory = categoryPicker.SelectedItem?.ToString() ?? "Sombreros";
        catalogList.ItemsSource = catalog.Where(item => item.Category == selectedCategory).ToList();
        if (catalogList.Items.Count > 0)
            catalogList.SelectedIndex = 0;
        UpdateCatalogDescription();
    }

    private void LoadPersistedUserAssets()
    {
        try
        {
            var info = new FileInfo(userCatalogPath);
            if (!info.Exists)
                return;
            if (info.Length <= 0 || info.Length > 2 * 1024 * 1024)
                throw new InvalidDataException("El catálogo local de objetos debe ocupar menos de 2 MB.");

            var saved = JsonSerializer.Deserialize<List<PersistedUserAsset>>(File.ReadAllText(userCatalogPath), JsonOptions)
                ?? throw new InvalidDataException("El catálogo local de objetos no contiene una lista válida.");
            if (saved.Count > 500)
                throw new InvalidDataException("El catálogo local supera el máximo de 500 objetos importados.");

            var importRoot = GetImportRootPrefix();
            foreach (var entry in saved)
            {
                if (string.IsNullOrWhiteSpace(entry.Id) || string.IsNullOrWhiteSpace(entry.Path))
                    continue;
                var path = Path.GetFullPath(entry.Path);
                if (!path.StartsWith(importRoot, StringComparison.OrdinalIgnoreCase) || !File.Exists(path))
                    continue;
                if (catalog.Any(item => string.Equals(item.Path, path, StringComparison.OrdinalIgnoreCase)))
                    continue;

                var category = SupportedCategories.Contains(entry.Category, StringComparer.OrdinalIgnoreCase)
                    ? entry.Category
                    : "Personalizados";
                catalog.Add(new WaifuSpriteAsset(
                    entry.Id.StartsWith("user-", StringComparison.Ordinal) ? entry.Id : "user-" + Guid.NewGuid().ToString("N"),
                    string.IsNullOrWhiteSpace(entry.Name) ? Path.GetFileNameWithoutExtension(path) : entry.Name,
                    category,
                    string.IsNullOrWhiteSpace(entry.Description) ? "Objeto local importado por el usuario." : entry.Description,
                    path,
                    Math.Clamp(entry.Width, 1, 16384),
                    Math.Clamp(entry.Height, 1, 16384),
                    entry.RemoveMatte));
            }
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or ArgumentException or NotSupportedException)
        {
            // A damaged optional asset catalog must never stop the avatar studio from opening.
            SetStatus("No se pudo restaurar la biblioteca de objetos importados: " + exception.GetBaseException().Message);
        }
    }

    private void RegisterImportedAsset(string path, string name, string category, BitmapSource image, bool removeMatte)
    {
        var fullPath = Path.GetFullPath(path);
        if (!fullPath.StartsWith(GetImportRootPrefix(), StringComparison.OrdinalIgnoreCase) || !File.Exists(fullPath))
            return;

        var existing = catalog.FirstOrDefault(item => string.Equals(item.Path, fullPath, StringComparison.OrdinalIgnoreCase));
        if (existing is not null)
        {
            var index = catalog.IndexOf(existing);
            catalog[index] = existing with { Category = category, RemoveMatte = removeMatte };
        }
        else
        {
            catalog.Add(new WaifuSpriteAsset(
                "user-" + Guid.NewGuid().ToString("N"),
                string.IsNullOrWhiteSpace(name) ? Path.GetFileNameWithoutExtension(fullPath) : name,
                category,
                "Objeto importado por el usuario. Archivo local; no se ha subido a Internet.",
                fullPath,
                image.PixelWidth,
                image.PixelHeight,
                removeMatte));
        }

        PersistUserAssetsCatalog();
        if (Equals(categoryPicker.SelectedItem, category))
            RefreshCatalog();
    }

    private string GetImportRootPrefix() =>
        Path.GetFullPath(importDirectory).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
        + Path.DirectorySeparatorChar;

    private void PersistUserAssetsCatalog()
    {
        string? temporaryPath = null;
        try
        {
            var importRoot = GetImportRootPrefix();
            var entries = catalog
                .Where(item => item.Id.StartsWith("user-", StringComparison.Ordinal) &&
                    item.Path.StartsWith(importRoot, StringComparison.OrdinalIgnoreCase) && File.Exists(item.Path))
                .TakeLast(500)
                .Select(item => new PersistedUserAsset(
                    item.Id, item.Name, item.Category, item.Description, Path.GetFullPath(item.Path),
                    item.Width, item.Height, item.RemoveMatte))
                .ToArray();

            temporaryPath = userCatalogPath + ".tmp";
            File.WriteAllText(temporaryPath, JsonSerializer.Serialize(entries, JsonOptions));
            File.Move(temporaryPath, userCatalogPath, overwrite: true);
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or ArgumentException)
        {
            SetStatus("El objeto está disponible durante esta sesión, pero no se pudo guardar el catálogo local: "
                + exception.GetBaseException().Message);
        }
        finally
        {
            if (temporaryPath is not null && File.Exists(temporaryPath))
            {
                try { File.Delete(temporaryPath); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
            }
        }
    }

    private void UpdateCatalogDescription()
    {
        if (catalogList.SelectedItem is WaifuSpriteAsset asset)
            SetStatus(asset.Description + (asset.Category == "Fondos" ? " Podés moverlo al fondo con «↓ Atrás»." : " Podés arrastrarlo, escalarlo, girarlo y cambiar su opacidad."));
    }

    private void AddSelectedCatalogAsset()
    {
        if (catalogList.SelectedItem is not WaifuSpriteAsset asset)
        {
            SetStatus("Elegí un recurso de la biblioteca primero.");
            return;
        }

        try
        {
            var frames = LoadFrames(asset.Path, asset.RemoveMatte);
            var isBackground = asset.Category == "Fondos";
            var size = DefaultSize(asset.Category, asset.Width, asset.Height);
            var x = isBackground ? 0 : DefaultX(asset.Category, size.Width);
            var y = isBackground ? 0 : DefaultY(asset.Category, size.Height);
            var layer = new SpriteLayer
            {
                Id = Guid.NewGuid(), Name = asset.Name, Category = asset.Category, Path = asset.Path,
                Frames = frames, X = x, Y = y, Width = isBackground ? canvasWidth : size.Width,
                Height = isBackground ? canvasHeight : size.Height, Scale = 1, Rotation = 0, Opacity = 1,
                Visible = true, ZIndex = isBackground ? -100 : NextZ(), RemoveMatte = asset.RemoveMatte
            };
            AddLayer(layer);
            SetStatus("Objeto añadido: " + asset.Name + ". Seleccionalo en el panel de capas para ajustar su posición.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo cargar el objeto: " + exception.GetBaseException().Message);
        }
    }

    private void ChooseBaseImage()
    {
        var dialog = new OpenFileDialog { Title = "Elegí tu PNG de personaje", Filter = "Imágenes compatibles|*.png;*.jpg;*.jpeg;*.bmp;*.gif", CheckFileExists = true };
        if (dialog.ShowDialog(this) == true)
            TryImportBaseImage(dialog.FileName);
    }

    private void TryImportBaseImage(string path)
    {
        try
        {
            var imported = CopyIntoWorkspace(path);
            var removeWhite = removeWhiteOnImport.IsChecked == true;
            var frames = LoadFrames(imported, removeWhite);
            var first = frames[0];
            var factor = Math.Min(900d / first.PixelWidth, 900d / first.PixelHeight);
            var width = Math.Max(1, first.PixelWidth * factor);
            var height = Math.Max(1, first.PixelHeight * factor);
            var processedPath = imported;
            if (removeWhite && !Path.GetExtension(imported).Equals(".gif", StringComparison.OrdinalIgnoreCase))
            {
                processedPath = Path.Combine(importDirectory, "base-" + Guid.NewGuid().ToString("N") + ".png");
                SavePng(frames[0], processedPath);
            }

            layers.RemoveAll(layer => layer.Category == "Personaje base");
            RefreshVisuals();
            AddLayer(new SpriteLayer
            {
                Id = Guid.NewGuid(), Name = "Personaje base · " + Path.GetFileName(path), Category = "Personaje base",
                Path = processedPath, Frames = frames, X = (canvasWidth - width) / 2, Y = (canvasHeight - height) / 2,
                Width = width, Height = height, Scale = 1, Rotation = 0, Opacity = 1, Visible = true,
                ZIndex = 100, RemoveMatte = removeWhite && Path.GetExtension(imported).Equals(".gif", StringComparison.OrdinalIgnoreCase)
            });
            RegisterImportedAsset(imported, Path.GetFileNameWithoutExtension(path), "Personalizados", first, removeWhite);
            SetStatus(removeWhite
                ? "Personaje importado. Se eliminó localmente el blanco conectado al borde; el archivo original no se modificó. Revisá los bordes claros y ajustá a mano si hace falta."
                : "Personaje importado sin quitar el fondo. Podés usar «Quitar fondo blanco a una imagen» después.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo importar el personaje: " + exception.GetBaseException().Message);
            MessageBox.Show(this, exception.GetBaseException().Message, "No se pudo importar la imagen", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void ChooseExternalAsset()
    {
        var dialog = new OpenFileDialog { Title = "Elegí un objeto o fondo para agregar", Filter = "Imágenes PNG/JPG/BMP/GIF|*.png;*.jpg;*.jpeg;*.bmp;*.gif", CheckFileExists = true };
        if (dialog.ShowDialog(this) != true) return;
        // The category selector doubles as the import destination, so users can classify
        // an imported eye/mouth/hat explicitly instead of silently forcing everything to Custom.
        var category = categoryPicker.SelectedItem?.ToString() ?? "Personalizados";
        TryImportObject(dialog.FileName, category);
    }

    private void ChooseImageForMatting()
    {
        var dialog = new OpenFileDialog { Title = "Elegí la imagen a la que querés quitarle el fondo blanco", Filter = "Imágenes|*.png;*.jpg;*.jpeg;*.bmp", CheckFileExists = true };
        if (dialog.ShowDialog(this) != true) return;
        try
        {
            var imported = CopyIntoWorkspace(dialog.FileName);
            var frame = LoadFrames(imported, true)[0];
            var output = Path.Combine(importDirectory, "matte-" + Guid.NewGuid().ToString("N") + ".png");
            SavePng(frame, output);
            var frames = LoadFrames(output, false);
            var size = DefaultSize("Personalizados", frames[0].PixelWidth, frames[0].PixelHeight);
            AddLayer(new SpriteLayer
            {
                Id = Guid.NewGuid(), Name = "Fondo blanco quitado · " + Path.GetFileName(dialog.FileName), Category = "Personalizados",
                Path = output, Frames = frames, X = DefaultX("Personalizados", size.Width), Y = DefaultY("Personalizados", size.Height),
                Width = size.Width, Height = size.Height, Scale = 1, Rotation = 0, Opacity = 1, Visible = true,
                ZIndex = NextZ(), RemoveMatte = false
            });
            RegisterImportedAsset(output, Path.GetFileNameWithoutExtension(dialog.FileName), "Personalizados", frames[0], removeMatte: false);
            SetStatus("Se creó una copia PNG con transparencia. El archivo original quedó intacto.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo eliminar el fondo: " + exception.GetBaseException().Message);
        }
    }

    private void TryImportObject(string path, string category)
    {
        try
        {
            var imported = CopyIntoWorkspace(path);
            var removeWhite = removeWhiteOnImport.IsChecked == true;
            var frames = LoadFrames(imported, removeWhite);
            var isBackground = category == "Fondos";
            var size = DefaultSize(category, frames[0].PixelWidth, frames[0].PixelHeight);
            var layer = new SpriteLayer
            {
                Id = Guid.NewGuid(), Name = Path.GetFileNameWithoutExtension(path), Category = category, Path = imported,
                Frames = frames, X = isBackground ? 0 : DefaultX(category, size.Width), Y = isBackground ? 0 : DefaultY(category, size.Height),
                Width = isBackground ? canvasWidth : size.Width, Height = isBackground ? canvasHeight : size.Height,
                Scale = 1, Rotation = 0, Opacity = 1, Visible = true, ZIndex = isBackground ? -100 : NextZ(), RemoveMatte = removeWhite
            };
            AddLayer(layer);
            RegisterImportedAsset(imported, Path.GetFileNameWithoutExtension(path), category, frames[0], removeWhite);
            SetStatus(Path.GetExtension(path).Equals(".gif", StringComparison.OrdinalIgnoreCase)
                ? "GIF agregado y animado en la vista previa. La exportación será una imagen PNG del fotograma visible."
                : "Objeto importado. Si el fondo blanco seguía conectado al borde se procesó localmente.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo importar el objeto: " + exception.GetBaseException().Message);
        }
    }

    private void ImportDroppedFile(string path)
    {
        var extension = Path.GetExtension(path);
        if (extension.Equals(".png", StringComparison.OrdinalIgnoreCase) ||
            extension.Equals(".jpg", StringComparison.OrdinalIgnoreCase) ||
            extension.Equals(".jpeg", StringComparison.OrdinalIgnoreCase) ||
            extension.Equals(".bmp", StringComparison.OrdinalIgnoreCase) ||
            extension.Equals(".gif", StringComparison.OrdinalIgnoreCase))
        {
            if (layers.All(layer => layer.Category != "Personaje base"))
                TryImportBaseImage(path);
            else
                TryImportObject(path, extension.Equals(".gif", StringComparison.OrdinalIgnoreCase) ? "Fondos" : "Personalizados");
        }
    }

    private string CopyIntoWorkspace(string path)
    {
        var source = Path.GetFullPath(path);
        var info = new FileInfo(source);
        if (!info.Exists || info.Length <= 0 || info.Length > MaxFileBytes)
            throw new InvalidDataException("Cada imagen debe existir y ocupar entre 1 byte y 25 MB.");
        var extension = Path.GetExtension(source).ToLowerInvariant();
        if (extension is not (".png" or ".jpg" or ".jpeg" or ".bmp" or ".gif"))
            throw new InvalidDataException("Los formatos admitidos son PNG, JPG, JPEG, BMP y GIF.");
        var target = Path.Combine(importDirectory, Guid.NewGuid().ToString("N") + extension);
        File.Copy(source, target, overwrite: false);
        return target;
    }

    private static List<BitmapSource> LoadFrames(string path, bool removeWhite)
    {
        using var stream = File.OpenRead(path);
        var decoder = BitmapDecoder.Create(stream, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
        if (decoder.Frames.Count == 0)
            throw new InvalidDataException("El archivo no contiene ningún fotograma válido.");
        if (decoder.Frames.Count > 90)
            throw new InvalidDataException("El GIF tiene más de 90 fotogramas. Reducí el GIF antes de importarlo.");
        long totalPixels = 0;
        var frames = new List<BitmapSource>(decoder.Frames.Count);
        foreach (var frame in decoder.Frames)
        {
            var width = frame.PixelWidth;
            var height = frame.PixelHeight;
            var pixels = checked((long)width * height);
            if (width <= 0 || height <= 0 || width > 16384 || height > 16384 || pixels > MaxFramePixels)
                throw new InvalidDataException("La imagen supera el límite de 16384 px por lado o 20 megapíxeles por fotograma.");
            totalPixels = checked(totalPixels + pixels);
            if (totalPixels > MaxGifPixels)
                throw new InvalidDataException("La suma de los fotogramas supera 30 megapíxeles. Importá una versión GIF más ligera.");
            var converted = new FormatConvertedBitmap(frame, PixelFormats.Bgra32, null, 0);
            converted.Freeze();
            if (!removeWhite)
            {
                frames.Add(converted);
                continue;
            }

            var stride = checked(width * 4);
            var bgra = new byte[checked(stride * height)];
            converted.CopyPixels(bgra, stride, 0);
            BorderConnectedMatteProcessor.RemoveNearWhiteBorder(bgra, width, height);
            var keyed = BitmapSource.Create(width, height, 96, 96, PixelFormats.Bgra32, null, bgra, stride);
            keyed.Freeze();
            frames.Add(keyed);
        }

        return frames;
    }

    private void AddLayer(SpriteLayer layer)
    {
        if (layers.Count >= MaximumLayers)
        {
            SetStatus($"El proyecto llegó al máximo de {MaximumLayers} capas.");
            return;
        }
        layers.Add(layer);
        AddVisual(layer);
        SelectLayer(layer.Id);
    }

    private void AddVisual(SpriteLayer layer)
    {
        var image = new Image { Source = layer.Frames[0], Stretch = layer.Category == "Fondos" ? Stretch.UniformToFill : Stretch.Fill, IsHitTestVisible = false };
        var border = new Border { Width = layer.Width, Height = layer.Height, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Child = image, Tag = layer.Id, Opacity = layer.Opacity, Cursor = Cursors.SizeAll };
        border.RenderTransformOrigin = new Point(.5, .5);
        border.RenderTransform = BuildTransform(layer);
        border.Visibility = layer.Visible ? Visibility.Visible : Visibility.Collapsed;
        border.MouseLeftButtonDown += (_, e) =>
        {
            SelectLayer(layer.Id);
            var origin = e.GetPosition(canvas);
            var startX = layer.X;
            var startY = layer.Y;
            if (!border.CaptureMouse()) return;
            e.Handled = true;
            MouseEventHandler? move = null;
            MouseButtonEventHandler? up = null;
            move = (_, moveEvent) =>
            {
                if (!border.IsMouseCaptured) return;
                var current = moveEvent.GetPosition(canvas);
                layer.X = Math.Clamp(startX + current.X - origin.X, -canvasWidth, canvasWidth * 2);
                layer.Y = Math.Clamp(startY + current.Y - origin.Y, -canvasHeight, canvasHeight * 2);
                Canvas.SetLeft(border, layer.X);
                Canvas.SetTop(border, layer.Y);
                LoadSelectedLayerTransform();
            };
            up = (_, upEvent) =>
            {
                border.ReleaseMouseCapture();
                border.MouseMove -= move;
                border.MouseLeftButtonUp -= up;
                upEvent.Handled = true;
            };
            border.MouseMove += move;
            border.MouseLeftButtonUp += up;
        };
        visuals[layer.Id] = border;
        canvas.Children.Add(border);
        Canvas.SetLeft(border, layer.X);
        Canvas.SetTop(border, layer.Y);
        Canvas.SetZIndex(border, layer.ZIndex);
        UpdateSelectionOutline();
        RefreshLayerList(layer.Id);
    }

    private void RefreshVisuals()
    {
        canvas.Children.Clear();
        visuals.Clear();
        foreach (var layer in layers.OrderBy(item => item.ZIndex).ToArray())
            AddVisualWithoutRefresh(layer);
        RefreshLayerList(selectedLayerId);
        UpdateSelectionOutline();
    }

    private void AddVisualWithoutRefresh(SpriteLayer layer)
    {
        var image = new Image { Source = layer.Frames[Math.Clamp(layer.FrameIndex, 0, layer.Frames.Count - 1)], Stretch = Stretch.Fill, IsHitTestVisible = false };
        var border = new Border { Width = layer.Width, Height = layer.Height, Background = Brushes.Transparent, BorderThickness = new Thickness(0), Child = image, Tag = layer.Id, Opacity = layer.Opacity, Cursor = Cursors.SizeAll };
        border.RenderTransformOrigin = new Point(.5, .5);
        border.RenderTransform = BuildTransform(layer);
        border.Visibility = layer.Visible ? Visibility.Visible : Visibility.Collapsed;
        border.MouseLeftButtonDown += (_, e) =>
        {
            SelectLayer(layer.Id);
            var origin = e.GetPosition(canvas);
            var startX = layer.X; var startY = layer.Y;
            if (!border.CaptureMouse()) return;
            e.Handled = true;
            MouseEventHandler? move = null; MouseButtonEventHandler? up = null;
            move = (_, moveEvent) =>
            {
                if (!border.IsMouseCaptured) return;
                var current = moveEvent.GetPosition(canvas);
                layer.X = Math.Clamp(startX + current.X - origin.X, -canvasWidth, canvasWidth * 2);
                layer.Y = Math.Clamp(startY + current.Y - origin.Y, -canvasHeight, canvasHeight * 2);
                Canvas.SetLeft(border, layer.X); Canvas.SetTop(border, layer.Y);
                LoadSelectedLayerTransform();
            };
            up = (_, upEvent) =>
            {
                border.ReleaseMouseCapture(); border.MouseMove -= move; border.MouseLeftButtonUp -= up; upEvent.Handled = true;
            };
            border.MouseMove += move; border.MouseLeftButtonUp += up;
        };
        visuals[layer.Id] = border;
        canvas.Children.Add(border);
        Canvas.SetLeft(border, layer.X); Canvas.SetTop(border, layer.Y); Canvas.SetZIndex(border, layer.ZIndex);
    }

    private void RefreshLayerList(Guid? selectId = null)
    {
        layerList.ItemsSource = layers.OrderByDescending(item => item.ZIndex)
            .Select(item => new LayerListEntry(item.Id, (item.Visible ? "● " : "○ ") + item.Name + " · " + item.Category))
            .ToList();
        var target = selectId ?? selectedLayerId;
        if (target.HasValue)
            layerList.SelectedItem = layerList.Items.Cast<LayerListEntry>().FirstOrDefault(item => item.Id == target.Value);
    }

    private void SelectLayer(Guid id)
    {
        selectedLayerId = layers.Any(layer => layer.Id == id) ? id : null;
        RefreshLayerList(selectedLayerId);
        UpdateSelectionOutline();
        LoadSelectedLayerTransform();
    }

    private void UpdateSelectionOutline()
    {
        foreach (var (id, border) in visuals)
        {
            var selected = id == selectedLayerId;
            border.BorderThickness = selected ? new Thickness(2) : new Thickness(0);
            border.BorderBrush = selected ? Brush("#D6AEFF") : Brushes.Transparent;
            border.Cursor = selected ? Cursors.SizeAll : Cursors.Hand;
        }
    }

    private void LoadSelectedLayerTransform()
    {
        if (layerList.SelectedItem is LayerListEntry entry && entry.Id != selectedLayerId)
            selectedLayerId = entry.Id;
        var layer = GetSelectedLayer();
        loadingTransform = true;
        xSlider.Value = Math.Clamp(layer?.X ?? 0, xSlider.Minimum, xSlider.Maximum);
        ySlider.Value = Math.Clamp(layer?.Y ?? 0, ySlider.Minimum, ySlider.Maximum);
        scaleSlider.Value = Math.Clamp(layer?.Scale ?? 1, scaleSlider.Minimum, scaleSlider.Maximum);
        rotationSlider.Value = Math.Clamp(layer?.Rotation ?? 0, rotationSlider.Minimum, rotationSlider.Maximum);
        opacitySlider.Value = Math.Clamp(layer?.Opacity ?? 1, opacitySlider.Minimum, opacitySlider.Maximum);
        loadingTransform = false;
        PreviewSelectedTransform();
        UpdateSelectionOutline();
    }

    private void PreviewSelectedTransform()
    {
        var layer = GetSelectedLayer();
        xValue.Text = $"X: {xSlider.Value:0} px";
        yValue.Text = $"Y: {ySlider.Value:0} px";
        scaleValue.Text = $"Tamaño: {scaleSlider.Value:P0}";
        rotationValue.Text = $"Giro: {rotationSlider.Value:0}°";
        opacityValue.Text = $"Opacidad: {opacitySlider.Value:P0}";
        if (loadingTransform || layer is null) return;
        layer.X = xSlider.Value;
        layer.Y = ySlider.Value;
        layer.Scale = scaleSlider.Value;
        layer.Rotation = rotationSlider.Value;
        layer.Opacity = opacitySlider.Value;
        if (visuals.TryGetValue(layer.Id, out var border))
        {
            border.RenderTransform = BuildTransform(layer);
            border.Opacity = layer.Opacity;
            Canvas.SetLeft(border, layer.X);
            Canvas.SetTop(border, layer.Y);
        }
    }

    private void ToggleSelectedLayer()
    {
        var layer = GetSelectedLayer();
        if (layer is null) return;
        layer.Visible = !layer.Visible;
        if (visuals.TryGetValue(layer.Id, out var border))
            border.Visibility = layer.Visible ? Visibility.Visible : Visibility.Collapsed;
        RefreshLayerList(layer.Id);
        SetStatus(layer.Name + (layer.Visible ? " visible." : " oculto."));
    }

    private void DuplicateSelectedLayer()
    {
        var selected = GetSelectedLayer();
        if (selected is null) return;
        if (layers.Count >= MaximumLayers) { SetStatus("Se alcanzó el máximo de capas."); return; }
        var duplicate = selected.Clone();
        duplicate.Id = Guid.NewGuid();
        duplicate.Name += " (copia)";
        duplicate.X = Math.Clamp(duplicate.X + 30, -canvasWidth, canvasWidth * 2);
        duplicate.Y = Math.Clamp(duplicate.Y + 30, -canvasHeight, canvasHeight * 2);
        duplicate.ZIndex = NextZ();
        AddLayer(duplicate);
    }

    private void MoveSelectedLayer(int direction)
    {
        var selected = GetSelectedLayer();
        if (selected is null) return;
        var ordered = layers.OrderBy(layer => layer.ZIndex).ToList();
        var index = ordered.FindIndex(layer => layer.Id == selected.Id);
        var next = index + Math.Sign(direction);
        if (next < 0 || next >= ordered.Count) return;
        (ordered[index].ZIndex, ordered[next].ZIndex) = (ordered[next].ZIndex, ordered[index].ZIndex);
        foreach (var layer in ordered)
            if (visuals.TryGetValue(layer.Id, out var border)) Canvas.SetZIndex(border, layer.ZIndex);
        RefreshVisuals();
        SelectLayer(selected.Id);
    }

    private void RemoveSelectedLayer()
    {
        var layer = GetSelectedLayer();
        if (layer is null) return;
        layers.Remove(layer);
        selectedLayerId = null;
        RefreshVisuals();
        SetStatus("Capa quitada del proyecto. El archivo de imagen original no se borra.");
    }

    private void ResetSelectedTransform()
    {
        var layer = GetSelectedLayer();
        if (layer is null) return;
        loadingTransform = true;
        xSlider.Value = layer.X; ySlider.Value = layer.Y; scaleSlider.Value = 1; rotationSlider.Value = 0; opacitySlider.Value = 1;
        loadingTransform = false;
        PreviewSelectedTransform();
    }

    private void AdvanceAnimatedLayers()
    {
        foreach (var layer in layers.Where(item => item.Frames.Count > 1 && item.Visible))
        {
            layer.FrameIndex = (layer.FrameIndex + 1) % layer.Frames.Count;
            if (visuals.TryGetValue(layer.Id, out var border) && border.Child is Image image)
                image.Source = layer.Frames[layer.FrameIndex];
        }
    }

    private void ExportComposite(bool createProfile)
    {
        var output = ChooseOutputPath();
        if (output is null) return;
        try
        {
            SavePng(RenderComposite(), output);
            SetStatus("PNG transparente exportado: " + output);
            if (createProfile)
                CompositeExported?.Invoke(output);
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo exportar el PNG: " + exception.GetBaseException().Message);
            MessageBox.Show(this, exception.GetBaseException().Message, "Exportación fallida", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private void ExportCompositeFor2D()
    {
        var output = ChooseOutputPath();
        if (output is null) return;
        try
        {
            SavePng(RenderComposite(), output);
            SetStatus("PNG exportado; se enviará al separador 2.5D local experimental.");
            CompositeExportedFor2D?.Invoke(output);
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo exportar el PNG: " + exception.GetBaseException().Message);
            MessageBox.Show(this, exception.GetBaseException().Message, "Exportación fallida", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private string? ChooseOutputPath()
    {
        var dialog = new SaveFileDialog { Title = "Exportar personaje PNG transparente", Filter = "PNG transparente|*.png", FileName = "waifu-pngtuber.png", AddExtension = true, DefaultExt = ".png" };
        return dialog.ShowDialog(this) == true ? dialog.FileName : null;
    }

    private BitmapSource RenderComposite()
    {
        var exportCanvas = new Canvas { Width = canvasWidth, Height = canvasHeight, Background = Brushes.Transparent, ClipToBounds = true };
        foreach (var layer in layers.Where(item => item.Visible).OrderBy(item => item.ZIndex))
        {
            var image = new Image
            {
                Source = layer.Frames[Math.Clamp(layer.FrameIndex, 0, layer.Frames.Count - 1)],
                Width = layer.Width,
                Height = layer.Height,
                Stretch = layer.Category == "Fondos" ? Stretch.UniformToFill : Stretch.Fill,
                Opacity = layer.Opacity,
                RenderTransformOrigin = new Point(.5, .5),
                RenderTransform = BuildTransform(layer)
            };
            exportCanvas.Children.Add(image);
            Canvas.SetLeft(image, layer.X);
            Canvas.SetTop(image, layer.Y);
        }

        exportCanvas.Measure(new Size(canvasWidth, canvasHeight));
        exportCanvas.Arrange(new Rect(0, 0, canvasWidth, canvasHeight));
        exportCanvas.UpdateLayout();
        var target = new RenderTargetBitmap(canvasWidth, canvasHeight, 96, 96, PixelFormats.Pbgra32);
        target.Render(exportCanvas);
        target.Freeze();
        return target;
    }

    private void SaveProject()
    {
        var dialog = new SaveFileDialog { Title = "Guardar proyecto de waifu", Filter = "Proyecto Waifu (*.waifu.json)|*.waifu.json|JSON (*.json)|*.json", FileName = "waifu-project.waifu.json" };
        if (dialog.ShowDialog(this) != true) return;
        try
        {
            var dto = new WaifuProjectDocument(
                canvasWidth,
                canvasHeight,
                layers.Select(layer => new WaifuProjectLayer(layer.Id, layer.Name, layer.Category, layer.Path, layer.X, layer.Y,
                    layer.Width, layer.Height, layer.Scale, layer.Rotation, layer.Opacity, layer.Visible, layer.ZIndex, layer.RemoveMatte, layer.FrameIndex)).ToList());
            File.WriteAllText(dialog.FileName, JsonSerializer.Serialize(dto, JsonOptions));
            SetStatus("Proyecto guardado con " + layers.Count + " capas. Las imágenes importadas permanecen en la carpeta local de VTuberBot.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo guardar el proyecto: " + exception.GetBaseException().Message);
        }
    }

    private void OpenProject()
    {
        var dialog = new OpenFileDialog { Title = "Abrir proyecto de waifu", Filter = "Proyecto Waifu (*.waifu.json;*.json)|*.waifu.json;*.json", CheckFileExists = true };
        if (dialog.ShowDialog(this) != true) return;
        try
        {
            var info = new FileInfo(dialog.FileName);
            if (info.Length <= 0 || info.Length > 2 * 1024 * 1024)
                throw new InvalidDataException("El archivo de proyecto debe ocupar menos de 2 MB.");
            var document = JsonSerializer.Deserialize<WaifuProjectDocument>(File.ReadAllText(dialog.FileName), JsonOptions)
                ?? throw new InvalidDataException("El archivo de proyecto no tiene un formato válido.");
            if (document.Layers.Count > MaximumLayers)
                throw new InvalidDataException($"El proyecto supera el máximo de {MaximumLayers} capas.");
            if (!IsSupportedCanvasSize(document.CanvasWidth, document.CanvasHeight))
                throw new InvalidDataException("El proyecto usa un tamaño de lienzo no admitido.");
            loadingCanvasSize = true;
            canvasSizePicker.SelectedItem = CanvasSizeLabel(document.CanvasWidth, document.CanvasHeight);
            loadingCanvasSize = false;
            SetCanvasDimensions(document.CanvasWidth, document.CanvasHeight);
            var loaded = new List<SpriteLayer>();
            foreach (var dto in document.Layers)
            {
                if (!File.Exists(dto.Path))
                    throw new FileNotFoundException("Falta una imagen usada por el proyecto: " + dto.Path);
                var frames = LoadFrames(dto.Path, dto.RemoveMatte);
                loaded.Add(new SpriteLayer
                {
                    Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id, Name = dto.Name, Category = dto.Category, Path = dto.Path, Frames = frames,
                    X = dto.X, Y = dto.Y, Width = dto.Width, Height = dto.Height, Scale = Math.Clamp(dto.Scale, .1, 3.5),
                    Rotation = Math.Clamp(dto.Rotation, -180, 180), Opacity = Math.Clamp(dto.Opacity, 0, 1),
                    Visible = dto.Visible, ZIndex = dto.ZIndex, RemoveMatte = dto.RemoveMatte, FrameIndex = frames.Count == 0 ? 0 : Math.Clamp(dto.FrameIndex, 0, frames.Count - 1)
                });
            }
            layers.Clear();
            layers.AddRange(loaded);
            selectedLayerId = null;
            RefreshVisuals();
            if (layers.Count > 0) SelectLayer(layers.OrderByDescending(layer => layer.ZIndex).First().Id);
            SetStatus("Proyecto abierto: " + layers.Count + " capas.");
        }
        catch (Exception exception)
        {
            SetStatus("No se pudo abrir el proyecto: " + exception.GetBaseException().Message);
            MessageBox.Show(this, exception.GetBaseException().Message, "Proyecto no válido", MessageBoxButton.OK, MessageBoxImage.Warning);
        }
    }

    private void ImportDroppedFileSafe(string path)
    {
        try { ImportDroppedFile(path); }
        catch (Exception exception) { SetStatus("No se pudo abrir el archivo arrastrado: " + exception.GetBaseException().Message); }
    }

    private SpriteLayer? GetSelectedLayer() =>
        selectedLayerId is Guid id ? layers.FirstOrDefault(layer => layer.Id == id) : null;

    private int NextZ() => layers.Count == 0 ? 200 : layers.Max(layer => layer.ZIndex) + 10;

    private static Transform BuildTransform(SpriteLayer layer)
    {
        var group = new TransformGroup();
        group.Children.Add(new ScaleTransform(layer.Scale, layer.Scale));
        group.Children.Add(new RotateTransform(layer.Rotation));
        return group;
    }

    private Size DefaultSize(string category, int originalWidth, int originalHeight)
    {
        return category switch
        {
            "Sombreros" => new Size(380, 275),
            "Ojos" => new Size(440, 190),
            "Bocas" => new Size(180, 135),
            "Emociones" => new Size(220, 220),
            "Fondos" => new Size(canvasWidth, canvasHeight),
            _ => FitWithin(originalWidth, originalHeight, 450, 450)
        };
    }

    private static Size FitWithin(int width, int height, double maxWidth, double maxHeight)
    {
        var factor = Math.Min(maxWidth / Math.Max(1, width), maxHeight / Math.Max(1, height));
        return new Size(Math.Max(1, width * factor), Math.Max(1, height * factor));
    }

    private double DefaultX(string category, double width) =>
        category switch
        {
            "Sombreros" => (canvasWidth - width) / 2,
            "Ojos" => (canvasWidth - width) / 2,
            "Bocas" => (canvasWidth - width) / 2,
            _ => (canvasWidth - width) / 2
        };

    private double DefaultY(string category, double height) =>
        category switch
        {
            "Sombreros" => 80,
            "Ojos" => 340,
            "Bocas" => 515,
            "Emociones" => 210,
            _ => (canvasHeight - height) / 2
        };

    private void SetStatus(string message) => status.Text = message;

    private static BitmapSource SavePng(BitmapSource image, string path)
    {
        var png = image.Format == PixelFormats.Bgra32 || image.Format == PixelFormats.Pbgra32
            ? image
            : new FormatConvertedBitmap(image, PixelFormats.Pbgra32, null, 0);
        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(png));
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        using var output = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None);
        encoder.Save(output);
        return image;
    }

    private static Brush CreateCheckerBrush()
    {
        var group = new DrawingGroup();
        using (var dc = group.Open())
        {
            dc.DrawRectangle(Brush("#242B3E"), null, new Rect(0, 0, 32, 32));
            dc.DrawRectangle(Brush("#30394F"), null, new Rect(0, 0, 16, 16));
            dc.DrawRectangle(Brush("#30394F"), null, new Rect(16, 16, 16, 16));
        }
        group.Freeze();
        return new DrawingBrush(group)
        {
            TileMode = TileMode.Tile,
            Viewport = new Rect(0, 0, 32, 32),
            ViewportUnits = BrushMappingMode.Absolute,
            Stretch = Stretch.Fill
        };
    }

    private static StackPanel Panel(string heading)
    {
        var panel = new StackPanel { Margin = new Thickness(10), Background = Brush("#151D30") };
        panel.Children.Add(new TextBlock { Text = heading, FontSize = 14, FontWeight = FontWeights.SemiBold, Foreground = Brush("#F4EAFF"), Margin = new Thickness(0, 0, 0, 8) });
        return panel;
    }

    private static Button ActionButton(string text, RoutedEventHandler action, bool primary = false)
    {
        var button = new Button
        {
            Content = text, MinHeight = 30, Padding = new Thickness(9, 5, 9, 5), Margin = new Thickness(0, 2, 6, 4),
            Background = Brush(primary ? "#5E4B89" : "#28344D"), Foreground = Brush("#F8FAFC"),
            BorderBrush = Brush(primary ? "#9D88D6" : "#45536E"), BorderThickness = new Thickness(1)
        };
        button.Click += action;
        return button;
    }

    private static SolidColorBrush Brush(string value)
    {
        var text = value.TrimStart('#');
        var color = text.Length == 6
            ? Color.FromRgb(
                byte.Parse(text[..2], System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture),
                byte.Parse(text.Substring(2, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture),
                byte.Parse(text.Substring(4, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture))
            : Color.FromArgb(255, 255, 255, 255);
        return new SolidColorBrush(color);
    }

    private sealed record LayerListEntry(Guid Id, string Display)
    {
        public override string ToString() => Display;
    }

    private sealed record PersistedUserAsset(
        string Id, string Name, string Category, string Description, string Path,
        int Width, int Height, bool RemoveMatte);

    private sealed class SpriteLayer
    {
        public Guid Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Path { get; set; } = string.Empty;
        public List<BitmapSource> Frames { get; set; } = [];
        public double X { get; set; }
        public double Y { get; set; }
        public double Width { get; set; }
        public double Height { get; set; }
        public double Scale { get; set; } = 1;
        public double Rotation { get; set; }
        public double Opacity { get; set; } = 1;
        public bool Visible { get; set; } = true;
        public int ZIndex { get; set; }
        public bool RemoveMatte { get; set; }
        public int FrameIndex { get; set; }

        public SpriteLayer Clone() => new()
        {
            Id = Id, Name = Name, Category = Category, Path = Path, Frames = Frames,
            X = X, Y = Y, Width = Width, Height = Height, Scale = Scale, Rotation = Rotation,
            Opacity = Opacity, Visible = Visible, ZIndex = ZIndex, RemoveMatte = RemoveMatte, FrameIndex = FrameIndex
        };
    }

    private sealed record WaifuProjectDocument(int CanvasWidth, int CanvasHeight, List<WaifuProjectLayer> Layers);
    private sealed record WaifuProjectLayer(Guid Id, string Name, string Category, string Path, double X, double Y,
        double Width, double Height, double Scale, double Rotation, double Opacity, bool Visible, int ZIndex,
        bool RemoveMatte, int FrameIndex);
}
